import { describe, expect, it, vi, beforeAll, afterAll } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { Dashboard } from './App';
import { RESEARCH_SNAPSHOT } from './test/fixtures/research';
import { change, valueAt } from './components/HistoryChart';

beforeAll(() => {
  vi.useFakeTimers({ toFake: ['Date'] });
  vi.setSystemTime(new Date('2026-10-02T16:05:00Z'));
});
afterAll(() => vi.useRealTimers());

describe('Dashboard with research data', () => {
  it('shows the headline sweep probability and range', () => {
    render(<Dashboard data={RESEARCH_SNAPSHOT} />);
    const hero = screen.getByRole('heading', { name: /democratic sweep/i }).closest('section')!;
    // Snapshot holds Polymarket 64, Kalshi 62, DDHQ 52 → mean 59 %.
    expect(within(hero).getByText('59%')).toBeInTheDocument();
    expect(within(hero).getByText(/range 52%–64%/)).toBeInTheDocument();
    expect(within(hero).getByText('32')).toBeInTheDocument();
    expect(within(hero).getByText(/updated 5 min ago/i)).toBeInTheDocument();
  });

  it('lists every source with its sweep value or implied range', () => {
    render(<Dashboard data={RESEARCH_SNAPSHOT} />);
    const section = screen.getByRole('heading', { name: 'By source' }).closest('section')!;
    expect(within(section).getAllByText('52.0%').length).toBeGreaterThan(0);
    // Silver Bulletin: Fréchet range 60–69 %
    expect(within(section).getAllByText(/60%–69%/).length).toBeGreaterThan(0);
  });

  const seatCard = (senate: HTMLElement) => within(senate).getByText(/^Dem seats/).parentElement!;

  it('marks Ohio as the tipping point and 52 Democratic seats', () => {
    render(<Dashboard data={RESEARCH_SNAPSHOT} />);
    const senate = screen.getByRole('heading', { name: /seat #51/i }).closest('section')!;
    expect(within(senate).getByText(/Tipping point/).querySelector('strong')).toHaveTextContent('OH');
    expect(seatCard(senate)).toHaveTextContent('52 / 100');
  });

  it('recomputes seats when the user flips Michigan and Maine to R', async () => {
    const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
    render(<Dashboard data={RESEARCH_SNAPSHOT} />);
    const senate = screen.getByRole('heading', { name: /seat #51/i }).closest('section')!;
    await user.click(within(senate).getByRole('button', { name: /Mike Rogers wins Michigan/ }));
    expect(seatCard(senate)).toHaveTextContent('51 / 100');
    await user.click(within(senate).getByRole('button', { name: /Susan Collins wins Maine/ }));
    expect(seatCard(senate)).toHaveTextContent('50 / 100');
    expect(seatCard(senate)).toHaveTextContent('1 short');
    await user.click(within(senate).getByRole('button', { name: 'Reset' }));
    expect(seatCard(senate)).toHaveTextContent('Majority');
  });

  it('defaults to the Senate trend tab and switches tabs', async () => {
    const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
    render(<Dashboard data={RESEARCH_SNAPSHOT} />);
    expect(screen.getByRole('tab', { name: 'Senate' })).toHaveAttribute('aria-selected', 'true');
    const sweep = screen.getByRole('tab', { name: 'Sweep' });
    await user.click(sweep);
    expect(sweep).toHaveAttribute('aria-selected', 'true');
  });

  it('announces chart values on keyboard navigation', async () => {
    const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
    render(<Dashboard data={RESEARCH_SNAPSHOT} />);
    await user.click(screen.getByRole('tab', { name: 'Sweep' }));
    screen.getByRole('img', { name: /sweep probability over time/i }).focus();
    await user.keyboard('{End}');
    expect(screen.getByText(/Oct 2: Polymarket 64\.0%, Kalshi 62\.0%/)).toBeInTheDocument();
  });
});

describe('history helpers', () => {
  const pts = RESEARCH_SNAPSHOT.history.sweep[1]!.points; // Kalshi 50 % → 62 %

  it('valueAt returns the last point at or before t', () => {
    expect(valueAt(pts, pts[0]!.t - 1)).toBeUndefined();
    expect(valueAt(pts, Infinity)?.p).toBe(0.62);
  });

  it('30-day change matches the research move (+12 pts for Kalshi sweep)', () => {
    expect(change(pts, 30)).toBeCloseTo(0.12, 6);
  });
});
